'use strict';
const $=s=>document.querySelector(s), KEY='jianwei.workspace.v2';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
let project=clone(exampleProject),selected='',view='map',editState=null,timer;
const specs={
 project:[['title','项目名称','text',true],['question','研究问题','text',true],['description','用途或背景','textarea'],['hypothesis','待检验假设','textarea'],['asOf','资料截至日期','date']],
 sources:[['title','资料标题','text',true],['kind','资料类型（如论文、访谈、个人笔记）','text'],['meta','作者、日期或资料背景','text'],['url','原文链接（可留空）','url'],['body','摘要或笔记','textarea',true],['boundary','证据边界 / 有什么不能证明','textarea']],
 claims:[['title','观点标题','text',true],['type','判断类型（如事实、假设、推断）','text'],['text','你的判断及理由','textarea',true],['question','还需要验证的问题','textarea'],['sources','关联资料','links']],
 evidence:[['title','证据线索标题','text',true],['stance','对当前假设的作用','stance',true],['text','为什么支持或挑战假设','textarea',true],['sources','关联资料','links']],
 stages:[['title','这一阶段的判断','text',true],['date','记录日期','date'],['text','当时的依据','textarea',true],['change','判断改变了什么 / 为什么','textarea'],['sources','关联资料','links']]
};
const names={project:'项目',sources:'资料',claims:'观点',evidence:'证据线索',stages:'判断记录'};
function validUrl(value){if(!value)return '';try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))throw 0;return u.href;}catch{throw new Error('原文链接须为完整的 http 或 https 地址。');}}
function validate(raw){
 if(!raw||typeof raw!=='object'||raw.version!==1)throw new Error('不是支持的见微项目文件（version 应为 1）。');
 const p={version:1};
 for(const [key] of specs.project){if(raw[key]!==undefined&&typeof raw[key]!=='string')throw new Error('项目字段必须是文字。');p[key]=raw[key]||'';if(p[key].length>20000)throw new Error('项目文字过长。');}
 if(!p.title.trim()||!p.question.trim())throw new Error('项目名称与研究问题不能为空。');
 p.conclusion=typeof raw.conclusion==='string'?raw.conclusion:'';if(p.conclusion.length>50000)throw new Error('结论过长。');
 for(const kind of ['sources','claims','evidence','stages']){
  if(!Array.isArray(raw[kind])||raw[kind].length>200)throw new Error('每类记录须为数组且不超过 200 项。');
  const ids=new Set();p[kind]=raw[kind].map(item=>{if(!item||typeof item.id!=='string'||!item.id||item.id.length>100||ids.has(item.id))throw new Error('记录编号缺失或重复。');ids.add(item.id);const clean={id:item.id};
   for(const [key,,type,required] of specs[kind]){if(type==='links'){if(!Array.isArray(item[key]||[])||(item[key]||[]).some(x=>typeof x!=='string'))throw new Error('关联资料编号格式不正确。');clean[key]=[...new Set(item[key]||[])];}else{if(item[key]!==undefined&&typeof item[key]!=='string')throw new Error('记录字段必须是文字。');clean[key]=item[key]||'';if(clean[key].length>20000)throw new Error('记录文字过长。');if(required&&!clean[key].trim())throw new Error('记录缺少必填字段。');if(type==='url')clean[key]=validUrl(clean[key]);if(type==='stance'&&!['support','challenge'].includes(clean[key]))throw new Error('证据立场须为 support 或 challenge。');}}
   return clean;
  });
 }
 const sourceIds=new Set(p.sources.map(s=>s.id));for(const item of [...p.claims,...p.evidence,...p.stages])if(item.sources.some(id=>!sourceIds.has(id)))throw new Error('存在找不到的关联资料，请检查项目文件。');return p;
}
try{const saved=localStorage.getItem(KEY);if(saved)project=validate(JSON.parse(saved));}catch{project=clone(exampleProject);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(project));$('#workspaceStatus').textContent='已自动保存到当前浏览器';$('#saveStatus').textContent='已保存 · 下载项目文件可备份';}catch{$('#workspaceStatus').textContent='浏览器无法保存，请下载项目文件备份';$('#saveStatus').textContent='保存失败，请下载项目文件';}}
function sourceButtons(ids=[]){return ids.map(id=>project.sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<button class="source-button" data-open-source="${esc(s.id)}"><small>${esc(s.kind||'资料')}</small>${esc(s.title)}</button>`).join('');}
function editButtons(kind,id){return `<button class="text-button" data-edit="${kind}" data-id="${esc(id)}">编辑${names[kind]}</button>`;}
function selectNode(id){selected=id;const n=project.claims.find(x=>x.id===id);$('#detail').innerHTML=n?`<span class="label">${esc(n.type||'观点')}</span><h2>${esc(n.title)}</h2><p class="multiline">${esc(n.text)}</p><h3>关联材料 · ${n.sources.length} 份</h3>${sourceButtons(n.sources)||'<p>暂未关联资料，编辑观点时可以勾选。</p>'}<p class="detail-question">${esc(n.question)}</p>${editButtons('claims',n.id)}`:'<h2>从一个观点开始</h2><p>先添加资料，再添加观点并勾选依据。点击观点卡片可以查看关联材料。</p>';
 document.querySelectorAll('[data-node]').forEach(b=>{b.classList.toggle('selected',b.dataset.node===id);b.setAttribute('aria-pressed',String(b.dataset.node===id));});}
function setView(name){view=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==name+'-view');document.querySelectorAll('.tab').forEach(el=>{el.classList.toggle('active',el.dataset.view===name);el.setAttribute('aria-selected',String(el.dataset.view===name));el.tabIndex=el.dataset.view===name?0:-1;});$('#viewHint').textContent={map:'观点 → 关联资料 → 证据边界',evidence:'支持与反证同时可见',timeline:'记录判断变化',library:'添加、编辑与核对资料',capex:'AI 案例补充 · 固定数据快照'}[name];}
function render(){
 $('#projectTitle').textContent=project.title;$('#projectQuestion').textContent=project.question;$('#projectDescription').textContent=project.description;$('#hypothesis').textContent=project.hypothesis||'先在「编辑项目」中写下一个待检验假设。';
 $('#summary').innerHTML=[['claims','观点'],['sources','资料'],['evidence','证据线索'],['stages','判断记录']].map(([k,label])=>`<div><span class="stat">${project[k].length}</span><span>${label}</span></div>`).join('')+`<div class="scope-note">${project.asOf?'资料截至 '+esc(project.asOf):'由你维护资料与判断'}</div>`;
 $('#claimCount').textContent=project.claims.length+' 个观点';
 $('#claimGrid').innerHTML=project.claims.map(n=>`<button class="claim-card" data-node="${esc(n.id)}"><span class="eyebrow">${esc(n.type||'观点')}</span><strong>${esc(n.title)}</strong><small>${n.sources.length} 份关联资料</small></button>`).join('')||'<p class="empty">尚无观点。点击「添加观点」开始；先保存资料，才有可勾选的依据。</p>';
 selectNode(project.claims.some(x=>x.id===selected)?selected:(project.claims[0]?.id||''));
 for(const stance of ['support','challenge'])$('#'+stance+'-list').innerHTML=project.evidence.filter(e=>e.stance===stance).map(e=>`<article class="evidence-card"><h4>${esc(e.title)}</h4><p class="multiline">${esc(e.text)}</p>${sourceButtons(e.sources)}${editButtons('evidence',e.id)}</article>`).join('')||'<p class="empty">尚无记录。添加证据时选择这一立场。</p>';
 $('#libraryContent').innerHTML='<div class="library-grid">'+project.sources.map(s=>`<article class="library-card"><span class="eyebrow">${esc(s.kind||'资料')} · ${esc(s.meta)}</span><h4>${esc(s.title)}</h4><p>${esc(s.body.slice(0,180))}${s.body.length>180?'…':''}</p><div class="library-actions"><button class="text-button" data-open-source="${esc(s.id)}">阅读详情</button>${editButtons('sources',s.id)}</div></article>`).join('')+'</div>'+(!project.sources.length?'<p class="empty">添加文章、访谈或自己的笔记。原文链接可留空，资料保存在当前浏览器。</p>':'');
 $('#timelineContent').innerHTML=project.stages.map((s,i)=>`<article class="stage-content"><div class="stage-index">${i+1}</div><div><p class="eyebrow">${esc(s.date||'未填写日期')}</p><h3>${esc(s.title)}</h3><p class="multiline">${esc(s.text)}</p><div class="stage-change"><small>修订理由</small><p class="multiline">${esc(s.change||'未填写')}</p></div><div class="stage-source">${sourceButtons(s.sources)}</div>${editButtons('stages',s.id)}</div></article>`).join('')||'<p class="empty">记录每次判断及其变化原因。新记录会追加在末尾。</p>';
 $('#conclusionText').value=project.conclusion;$('#capex-tab').hidden=!(project.sources.some(s=>s.id==='r4'&&s.url===exampleProject.sources.find(x=>x.id==='r4').url));if($('#capex-tab').hidden&&view==='capex')view='map';setView(view);
}
function openSource(id){const s=project.sources.find(s=>s.id===id);if(!s)return;$('#sourceContent').innerHTML=`<h2>${esc(s.title)}</h2><p class="source-meta">${esc(s.kind)} · ${esc(s.meta)}</p><div class="source-body">${esc(s.body)}</div>${s.url?`<a class="original-link" href="${esc(validUrl(s.url))}" target="_blank" rel="noopener noreferrer">阅读原文 ↗</a>`:''}<p class="source-caveat">证据边界：${esc(s.boundary||'尚未填写，请自行核对适用范围。')}</p>${editButtons('sources',s.id)}`;$('#sourceDialog').showModal();}
function openEditor(kind,id){if($('#sourceDialog').open)$('#sourceDialog').close();const item=kind==='project'?project:project[kind].find(x=>x.id===id)||{};editState={kind,id};$('#editorTitle').textContent=(kind==='project'||id?'编辑':'添加')+names[kind];$('#editorError').textContent='';$('#deleteItem').hidden=kind==='project'||!id;
 $('#editorFields').innerHTML=specs[kind].map(([key,label,type,required])=>{const value=item[key]||'';const title=`${label}${required?' *':''}`;if(type==='links')return `<fieldset><legend>${title}</legend>${project.sources.map(s=>`<label class="check-label"><input type="checkbox" name="sources" value="${esc(s.id)}" ${(item.sources||[]).includes(s.id)?'checked':''}>${esc(s.title)}</label>`).join('')||'<p>还没有资料，先保存当前内容，再去资料页添加。</p>'}</fieldset>`;
 if(type==='stance')return `<label>${title}<select name="${key}"><option value="support" ${value==='support'?'selected':''}>支持当前假设</option><option value="challenge" ${value==='challenge'?'selected':''}>挑战当前假设</option></select></label>`;
 return `<label>${title}${type==='textarea'?`<textarea name="${key}" rows="4" ${required?'required':''} maxlength="20000">${esc(value)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="20000">`}</label>`;}).join('');$('#editorDialog').showModal();}
$('#editorForm').addEventListener('submit',event=>{event.preventDefault();const {kind,id}=editState;const data=new FormData(event.target);const item=kind==='project'?{...project}:{id:id||crypto.randomUUID()};try{
 for(const [key,,type,required] of specs[kind]){item[key]=type==='links'?data.getAll(key):String(data.get(key)||'').trim();if(required&&!item[key])throw new Error('请填写全部必填项。');if(type==='url')item[key]=validUrl(item[key]);}
 const candidate=clone(project);if(kind==='project')Object.assign(candidate,item);else if(id)candidate[kind][candidate[kind].findIndex(x=>x.id===id)]=item;else candidate[kind].push(item);project=validate(candidate);persist();render();$('#editorDialog').close();toast('已保存'+names[kind]);
 }catch(e){$('#editorError').textContent=e.message;}});
$('#deleteItem').addEventListener('click',()=>{const {kind,id}=editState;if(!confirm('删除这项记录？删除资料会同时移除其他记录中的关联；请先下载备份。'))return;project[kind]=project[kind].filter(x=>x.id!==id);if(kind==='sources')for(const group of ['claims','evidence','stages'])for(const item of project[group])item.sources=item.sources.filter(x=>x!==id);persist();render();$('#editorDialog').close();});
function download(text,type,filename){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportProject(){project.conclusion=$('#conclusionText').value;download(JSON.stringify(project,null,2),'application/json',project.title.replace(/[\\/:*?"<>|]/g,'-')+'.json');toast('项目文件已下载，可导入后继续改写');}
function exportMarkdown(){project.conclusion=$('#conclusionText').value;const refs=ids=>ids.map(id=>project.sources.find(s=>s.id===id)).filter(Boolean).map(s=>s.url?`[${s.title}](${s.url})`:s.title).join('、')||'尚未关联';const md=`# ${project.title}\n\n## 研究问题\n${project.question}\n\n${project.description}\n\n## 待检验假设\n${project.hypothesis||'未填写'}\n\n## 当前结论\n${project.conclusion||'未填写'}\n\n## 观点与依据\n${project.claims.map(c=>`### ${c.title}\n${c.type}\n\n${c.text}\n\n资料：${refs(c.sources)}\n\n待验证：${c.question}`).join('\n\n')}\n\n## 证据对照\n${project.evidence.map(e=>`### ${e.stance==='support'?'支持':'挑战'}：${e.title}\n${e.text}\n\n资料：${refs(e.sources)}`).join('\n\n')}\n\n## 资料与出处\n${project.sources.map(s=>`### ${s.title}\n${s.kind} · ${s.meta}\n${s.url}\n\n${s.body}\n\n证据边界：${s.boundary||'未填写'}`).join('\n\n')}\n\n## 判断记录\n${project.stages.map(s=>`### ${s.date} ${s.title}\n${s.text}\n\n修订理由：${s.change}\n\n资料：${refs(s.sources)}`).join('\n\n')}\n\n---\n由见微导出；资料截至：${project.asOf||'未填写'}。内容由用户维护，工具不自动核实事实。\n`;download(md,'text/markdown;charset=utf-8',project.title.replace(/[\\/:*?"<>|]/g,'-')+'.md');toast('已导出带出处的研究报告');}
function replaceProject(next){if(!confirm('这会替换当前工作区。未下载的记录只能留在当前浏览器；建议先下载项目文件。继续吗？'))return false;project=next;selected='';view='map';persist();render();return true;}
const actions={newProject:()=>{if(replaceProject({version:1,title:'我的研究项目',question:'我想解决的具体问题是什么？',description:'写下问题、添加资料，再用支持与反对证据检验判断。',hypothesis:'',asOf:'',conclusion:'',sources:[],claims:[],evidence:[],stages:[]}))openEditor('project');},loadExample:()=>replaceProject(clone(exampleProject)),importProject:()=>$('#projectFile').click(),exportProject};
for(const [id,fn] of Object.entries(actions))$('#'+id).addEventListener('click',fn);
$('#projectFile').addEventListener('change',async e=>{const f=e.target.files[0];try{if(!f)return;if(f.size>2*1024*1024)throw new Error('项目文件须小于 2 MB。');const next=validate(JSON.parse(await f.text()));if(replaceProject(next))toast('已导入，可继续编辑');}catch(err){toast('导入失败：'+(err instanceof SyntaxError?'文件不是有效 JSON。':err.message));}finally{e.target.value='';}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.node)selectNode(b.dataset.node);if(b.dataset.view)setView(b.dataset.view);if(b.dataset.openSource)openSource(b.dataset.openSource);if(b.dataset.add)openEditor(b.dataset.add);if(b.dataset.edit)openEditor(b.dataset.edit,b.dataset.id);if(b.dataset.action)actions[b.dataset.action]();});
$('#editProject').addEventListener('click',()=>openEditor('project'));$('#export').addEventListener('click',exportMarkdown);$('#conclusionText').addEventListener('input',()=>{project.conclusion=$('#conclusionText').value;persist();});$('#saveConclusion').addEventListener('click',()=>{project.conclusion=$('#conclusionText').value;persist();toast('判断已保存');});$('#help').addEventListener('click',()=>$('#helpDialog').showModal());
for(const [button,dialog] of [['closeSource','sourceDialog'],['closeEditor','editorDialog'],['cancelEditor','editorDialog'],['closeHelp','helpDialog']])$('#'+button).addEventListener('click',()=>$('#'+dialog).close());
$('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...document.querySelectorAll('.tab')].filter(x=>!x.hidden),i=tabs.indexOf(e.target);if(i<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setView(tabs[next].dataset.view);tabs[next].focus();});
project=validate(project);render();
